const urls = [
  "https://forgejo.org/docs/latest/admin/backup-and-restore/",
  "https://forgejo.org/docs/latest/admin/backup-restore/",
  "https://forgejo.org/docs/latest/admin/",
  "https://forgejo.org/docs/next/admin/backup-and-restore/",
];
const out = {};
for (const u of urls) {
  try {
    const r = await fetch(u, { redirect: "follow" });
    out[u] = r.status;
  } catch (e) {
    out[u] = "ERR " + e.message;
  }
}
return out;

