const res = await fetch("https://forgejo.org/docs/latest/admin/setup/backup/", { redirect: "follow" });
const html = await res.text();
// strip tags roughly
const text = html.replace(/<script[\s\S]*?<\/script>/gi,"").replace(/<style[\s\S]*?<\/style>/gi,"").replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/\s+/g," ");
const idx = text.toLowerCase().indexOf("retain");
const idxApp = text.toLowerCase().indexOf("app.ini");
const idxCron = text.toLowerCase().indexOf("cron.backup");
return { status: res.status, len: html.length, aroundRetain: idx>=0 ? text.slice(Math.max(0,idx-600), idx+600) : null, appIni: idxApp>=0?text.slice(Math.max(0,idxApp-300),idxApp+300):null, cron: idxCron>=0?text.slice(Math.max(0,idxCron-300),idxCron+500):null };

