const res = await fetch("https://forgejo.org/docs/latest/admin/config-cheat-sheet/", { redirect: "follow" });
const html = await res.text();
let text = html.replace(/<script[\s\S]*?<\/script>/gi,"").replace(/<style[\s\S]*?<\/style>/gi,"").replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/\s+/g," ");
const lower = text.toLowerCase();
const out = {};
for (const t of ["backup_retain","cron.backup","backup","retain"]) {
  const i = lower.indexOf(t);
  out[t] = i>=0 ? text.slice(Math.max(0,i-200), i+300) : "NOT FOUND";
}
return { status: res.status, ...out };

